"""Unique usernames on a per-key compare-and-swap store.

Records: ("name", n) -> holder or None; ("user", u) -> name or None.
The name record is the claim: a CAS on it decides who gets a name. A user's own
record is only written by that user's calls, which never overlap.
Rename claims the new name, points the user at it, then frees the old name, so
a name is never held by two users and never lost.
"""
import re

_VALID = re.compile(r"[a-z0-9-]{1,16}")


def _norm(name):
    if not isinstance(name, str):
        return None
    name = name.lower()
    return name if _VALID.fullmatch(name) else None


class Registry:
    def __init__(self, store):
        self._s = store

    def _claim(self, user, name):
        """Make `user` the holder of `name` if free (or already theirs)."""
        key = ("name", name)
        while True:
            version, holder = self._s.load(key)
            if holder == user:
                return True
            if holder is not None:
                return False
            if self._s.compare_swap(key, version, user):
                return True

    def _set(self, key, value):
        while True:
            version, _ = self._s.load(key)
            if self._s.compare_swap(key, version, value):
                return

    def _release(self, user, name):
        key = ("name", name)
        while True:
            version, holder = self._s.load(key)
            if holder != user:
                return
            if self._s.compare_swap(key, version, None):
                return

    def register(self, user, name):
        name = _norm(name)
        if name is None:
            return False
        _, current = self._s.load(("user", user))
        if current is not None:
            return current == name
        if not self._claim(user, name):
            return False
        self._set(("user", user), name)
        return True

    def rename(self, user, new_name):
        new_name = _norm(new_name)
        if new_name is None:
            return False
        _, current = self._s.load(("user", user))
        if current is None:
            return False
        if current == new_name:
            return True
        if not self._claim(user, new_name):
            return False
        self._set(("user", user), new_name)
        self._release(user, current)
        return True

    def owner(self, name):
        name = _norm(name)
        if name is None:
            return None
        return self._s.load(("name", name))[1]

    def name_of(self, user):
        return self._s.load(("user", user))[1]
EOF
cat > Names.p <<'EOF'
// Model of the Registry algorithm over a per-key CAS store.
// Keys: 0..1 are names, 2..3 are users (user u uses key 2+u). Values: -1 = none, else int.
event eLoad: (client: machine, key: int);
event eLoadR: (version: int, value: int);
event eCas: (client: machine, key: int, version: int, value: int);
event eCasR: (ok: bool);
event eCommit: (key: int, value: int);
event eDone;
event eQuiet;
event eResult: (user: int, op: int, name: int, ok: bool);

// Contract: a name never has two holders; at quiescence name and user records agree.
spec Contract observes eCommit, eQuiet {
  var rec: map[int, int];
  start state S {
    entry { var i: int; while (i < 4) { rec[i] = -1; i = i + 1; } }
    on eCommit do (p: (key: int, value: int)) {
      var k: int;
      if (p.key < 2 && p.value >= 0) {
        assert rec[p.key] == -1 || rec[p.key] == p.value, "name claimed while held by another user";
      }
      rec[p.key] = p.value;
    }
    on eQuiet do {
      var n: int; var u: int;
      n = 0;
      while (n < 2) {
        if (rec[n] >= 0) { assert rec[2 + rec[n]] == n, "owner(n)=u but name_of(u)!=n"; }
        n = n + 1;
      }
      u = 0;
      while (u < 2) {
        if (rec[2 + u] >= 0) { assert rec[rec[2 + u]] == u, "name_of(u)=n but owner(n)!=u"; }
        u = u + 1;
      }
    }
  }
}

machine Store {
  var ver: map[int, int];
  var val: map[int, int];
  start state Serving {
    entry { var i: int; while (i < 4) { ver[i] = 0; val[i] = -1; i = i + 1; } }
    on eLoad do (p: (client: machine, key: int)) {
      send p.client, eLoadR, (version = ver[p.key], value = val[p.key]);
    }
    on eCas do (p: (client: machine, key: int, version: int, value: int)) {
      if (ver[p.key] == p.version) {
        ver[p.key] = p.version + 1; val[p.key] = p.value;
        announce eCommit, (key = p.key, value = p.value);
        send p.client, eCasR, (ok = true,);
      } else {
        send p.client, eCasR, (ok = false,);
      }
    }
  }
}

// Each client is one user (id 0 or 1) that registers a name, then renames to another.
machine Client {
  var store: Store;
  var main: machine;
  var me: int;
  start state Run {
    entry (a: (store: Store, main: machine, me: int)) {
      var n1: int; var n2: int; var ok: bool;
      store = a.store; main = a.main; me = a.me;
      n1 = choose(2);
      ok = Register(n1);
      n2 = choose(2);
      if (ok) { ok = Rename(n2); }
      send main, eDone;
    }
  }
  fun Load(key: int): (version: int, value: int) {
    var r: (version: int, value: int);
    send store, eLoad, (client = this, key = key);
    receive { case eLoadR: (x: (version: int, value: int)) { r = x; } }
    return r;
  }
  fun Cas(key: int, version: int, value: int): bool {
    var r: bool;
    send store, eCas, (client = this, key = key, version = version, value = value);
    receive { case eCasR: (x: (ok: bool)) { r = x.ok; } }
    return r;
  }
  fun Claim(name: int): bool {
    var r: (version: int, value: int);
    while (true) {
      r = Load(name);
      if (r.value == me) { return true; }
      if (r.value >= 0) { return false; }
      if (Cas(name, r.version, me)) { return true; }
    }
    return false;
  }
  fun SetUser(value: int) {
    var r: (version: int, value: int);
    while (true) {
      r = Load(2 + me);
      if (Cas(2 + me, r.version, value)) { return; }
    }
  }
  fun Release(name: int) {
    var r: (version: int, value: int);
    while (true) {
      r = Load(name);
      if (r.value != me) { return; }
      if (Cas(name, r.version, -1)) { return; }
    }
  }
  fun Register(name: int): bool {
    var cur: (version: int, value: int);
    cur = Load(2 + me);
    if (cur.value >= 0) { return cur.value == name; }
    if (!Claim(name)) { return false; }
    SetUser(name);
    return true;
  }
  fun Rename(name: int): bool {
    var cur: (version: int, value: int);
    cur = Load(2 + me);
    if (cur.value < 0) { return false; }
    if (cur.value == name) { return true; }
    if (!Claim(name)) { return false; }
    SetUser(name);
    Release(cur.value);
    return true;
  }
}

machine Main {
  start state Init {
    entry {
      var s: Store;
      s = new Store();
      new Client((store = s, main = this, me = 0));
      new Client((store = s, main = this, me = 1));
      receive { case eDone: { } }
      receive { case eDone: { } }
      announce eQuiet;
    }
  }
}

test tcTwoUsers [main=Main]: assert Contract in { Main, Store, Client };
